function timestamp(){return new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14)+'-'+crypto.randomBytes(4).toString('hex');}
function captureBackup(){const dir='/var/backups/prhm-host-actions-v14-honartik-iticket-'+timestamp();fs.mkdirSync(dir,{recursive:false,mode:0o700});const states=[];for(const [key,file] of Object.entries(PATHS)){const existed=fs.existsSync(file);const state={key,file,existed,mode:existed?modeOf(file,0o600):null,backup:null};if(existed){if(!regular(file))fail('unsafe_backup_source:'+file);state.backup=path.join(dir,key+'.bak');fs.copyFileSync(file,state.backup,fs.constants.COPYFILE_EXCL);fs.chmodSync(state.backup,0o600);}states.push(state);}return{dir,states};}
function restoreBackup(backup){for(const state of backup.states){try{fs.unlinkSync(state.file)}catch(error){if(error.code!=='ENOENT')throw error;}if(state.existed){fs.mkdirSync(path.dirname(state.file),{recursive:true,mode:0o755});const tmp=state.file+'.v14-rollback-'+process.pid+'-'+Date.now();fs.copyFileSync(state.backup,tmp,fs.constants.COPYFILE_EXCL);fs.chmodSync(tmp,state.mode);fs.renameSync(tmp,state.file);}}}

function acquireLock(){
  for(let attempt=0;attempt<4;attempt++){
    try{
      const fd=fs.openSync(LOCK_FILE,'wx',0o600);
      try{fs.writeFileSync(fd,String(process.pid)+'\n');fs.fsyncSync(fd);}finally{fs.closeSync(fd);}
      return()=>{try{if(fs.readFileSync(LOCK_FILE,'utf8').trim()===String(process.pid))fs.unlinkSync(LOCK_FILE);}catch{}};
    }catch(error){
      if(error.code!=='EEXIST')throw error;
      const st=fs.lstatSync(LOCK_FILE);if(!st.isFile()||st.isSymbolicLink())fail('unsafe_install_lock');
      let pid=0;try{pid=Number(fs.readFileSync(LOCK_FILE,'utf8').trim())}catch{}
      let alive=false;if(Number.isInteger(pid)&&pid>1){try{process.kill(pid,0);alive=true}catch(e){if(e.code!=='ESRCH')throw e;}}
      if(alive)fail('install_lock_held');
      const now=fs.lstatSync(LOCK_FILE);if(now.dev!==st.dev||now.ino!==st.ino)continue;
      fs.unlinkSync(LOCK_FILE);
    }
  }
  fail('install_lock_acquire_failed');
}
