function verifyCommittedJournal(j){if(j.phase!=='committed'||!j.installed_sha256||typeof j.installed_sha256!=='object')fail('committed_journal_invalid');for(const key of Object.keys(PATHS)){const expected=j.installed_sha256[key];if(typeof expected!=='string'||sha(read(PATHS[key]))!==expected)fail('committed_install_sha_mismatch:'+key);}const policy=JSON.parse(read(PATHS.policy).toString('utf8'));if(policy.version!==POLICY_VERSION||!policyBindingValid(policy))fail('committed_policy_invalid');for(const key of ['base','executor','mcp'])if(!read(PATHS[key]).toString('utf8').includes(ACTION))fail('committed_action_missing:'+key);return j.installed_sha256;}

