function unixHealth(socketPath){return new Promise(resolve=>{const req=http.request({socketPath,path:'/health',method:'GET'},res=>{res.resume();resolve(res.statusCode===200)});req.setTimeout(2000,()=>{req.destroy();resolve(false)});req.on('error',()=>resolve(false));req.end();});}
function tcpHealth(port){return new Promise(resolve=>{const req=http.request({host:'127.0.0.1',port,path:'/health',method:'GET'},res=>{res.resume();resolve(res.statusCode===200)});req.setTimeout(2000,()=>{req.destroy();resolve(false)});req.on('error',()=>resolve(false));req.end();});}
async function waitFor(fn,label){for(let i=0;i<30;i++){if(await fn())return true;await new Promise(r=>setTimeout(r,500));}fail('health_timeout:'+label);}
async function verifyHealth(){for(const s of SERVICES)await waitFor(()=>Promise.resolve(serviceActive(s)),s);await waitFor(()=>unixHealth('/run/prhm-agent-selfmaint/selfmaint.sock'),'selfmaint');await waitFor(()=>unixHealth('/run/prhm-agent-selfmaint-exec/exec.sock'),'selfmaint-exec');await waitFor(()=>tcpHealth(8123),'mcp');return true;}
