async function install(){const unlock=acquireLock();try{let journal=loadJournal();if(journal?.phase==='committed'){const installed_sha256=verifyCommittedJournal(journal);return{ok:true,schema_version:'prhm.host-action-install-result.v1',installed:true,already_installed:true,version:VERSION,action:ACTION,helper_sha256:HELPER_SHA,installed_sha256,approval_policy_version:POLICY_VERSION,control_plane_mutation:false,production_mutation:false,production_application_tree_mutation:false,database_mutation:false,business_mutation:false,external_send:false,external_network:false,token_read:false,deploy:false,rollback:{performed:false},backup_dir:journal.backup_dir};}if(journal?.phase==='prepared'){await recoverPreparedJournal(journal);journal=null;}const pf=preflightCore();const patched=buildPatched();const backup=captureBackup();const prepared=writePreparedJournal(backup);let mutated=false;try{atomicBytes(PATHS.helper,patched.helper,0o755);mutated=true;atomicText(PATHS.base,patched.base,modeOf(PATHS.base,0o755));atomicText(PATHS.executor,patched.executor,modeOf(PATHS.executor,0o755));atomicText(PATHS.mcp,patched.mcp,modeOf(PATHS.mcp,0o644));atomicText(PATHS.policy,patched.policy,modeOf(PATHS.policy,0o644));JSON.parse(read(PATHS.policy).toString('utf8'));restartServices();await verifyHealth();const installed_sha256=verifyInstalled(patched);writeCommittedJournal(prepared,installed_sha256);return{ok:true,schema_version:'prhm.host-action-install-result.v1',installed:true,version:VERSION,action:ACTION,helper_sha256:HELPER_SHA,installed_sha256,approval_policy_version:POLICY_VERSION,health:{services:true,base:true,executor:true,mcp:true},control_plane_mutation:true,production_mutation:true,production_application_tree_mutation:false,database_mutation:false,business_mutation:false,external_send:false,external_network:false,token_read:false,deploy:false,rollback:{performed:false},backup_dir:backup.dir,preflight:pf};}catch(error){if(mutated){try{restoreBackup(backup);restartServices();await verifyHealth();verifyRestoredJournal(prepared);try{fs.unlinkSync(JOURNAL)}catch(e){if(e.code!=='ENOENT')throw e;}}catch(rb){throw new Error('v14_install_failed_and_rollback_failed:'+String(error.message||error)+':'+String(rb.message||rb));}}else{try{fs.unlinkSync(JOURNAL)}catch(e){if(e.code!=='ENOENT')throw e;}}throw new Error('v14_install_failed_rolled_back:'+String(error.message||error));}}finally{unlock();}}
